mapper.select:
SELECT  FROM campaign
WHERE workspace_id = #{workspaceId}
ORDER BY updated_at DESC, id DESC

SELECT  FROM campaign
WHERE workspace_id = #{workspaceId} AND id = #{id}
FOR UPDATE

mapper.update:
UPDATE campaign
SET name = #{name}, objective = #{objective}, type = #{type}, status = #{status},
    owner_user_id = #{ownerUserId}, budget_amount = #{budgetAmount},
    budget_currency = #{budgetCurrency}, start_at = #{startAt}, end_at = #{endAt},
    parent_campaign_id = #{parentCampaignId}
WHERE workspace_id = #{workspaceId} AND id = #{id}

mapper.select:
SELECT COALESCE(MAX(version), 0) + 1
FROM campaign_audience_snapshot
WHERE workspace_id = #{workspaceId} AND campaign_id = #{campaignId}

SELECT  FROM campaign_audience_snapshot
WHERE workspace_id = #{workspaceId}
  AND campaign_id = #{campaignId}
  AND version = #{version}

SELECT  FROM campaign_audience_member
WHERE workspace_id = #{workspaceId} AND snapshot_id = #{snapshotId}
ORDER BY record_id

SELECT id FROM person
WHERE workspace_id = #{workspaceId}
  AND id IN #{id}
  AND (suspended_at IS NOT NULL OR provision_ceased_at IS NOT NULL)

SELECT p.id FROM person p
WHERE p.workspace_id = #{workspaceId}
  AND p.id IN #{id}
  AND p.email IS NOT NULL
  AND EXISTS (
    SELECT 1 FROM suppression_entry suppression
    WHERE suppression.workspace_id = #{workspaceId}
      AND suppression.channel = #{channel}
      AND suppression.address = LOWER(TRIM(p.email)) COLLATE utf8mb4_bin
  )

SELECT person_id FROM contact_channel_consent
WHERE workspace_id = #{workspaceId}
  AND person_id IN #{id}
  AND channel = #{channel}
  AND purpose = #{purpose}
  AND status = 'granted'

SELECT person_id FROM contact_channel_consent
WHERE workspace_id = #{workspaceId}
  AND person_id IN #{id}
  AND channel = #{channel}
  AND purpose = #{purpose}
  AND status = 'revoked'

SELECT DISTINCT suppression.address FROM suppression_entry suppression
WHERE suppression.workspace_id = #{workspaceId}
  AND suppression.channel = #{channel}
  AND suppression.address COLLATE utf8mb4_bin IN
    #{address}
